('0377b1d1-87df-55e3-a6a3-14883962a4f3', $c$js-arrays-002$c$, $c$single_choice$c$, $c$What does this print?$c$, $c${"code":"const a = [1, 2, 3, 4];\nconst b = a.slice(1, 3);\nconst c = a.splice(1, 2);\nconsole.log(a, b, c);","options":["[1, 4] [2, 3] [2, 3]","[1, 2, 3, 4] [2, 3] [2, 3]","[1, 4] [2, 3, 4] [2, 3]","[1, 4] [2, 3] [1, 4]"]}$c$::jsonb, $c$slice copies; splice removes in place and returns the removed items.$c$, 1, 1, 'published', array[$c$splice$c$, $c$slice$c$]::text[]),
('b3604c09-0cba-5979-b253-c7f4f922895e', $c$js-arrays-003$c$, $c$single_choice$c$, $c$What does this print?$c$, $c${"code":"const original = [3, 1, 2];\nconst alias = original;\nconst copy = [...original];\nalias.sort();\nconsole.log(original, copy);","options":["[1, 2, 3] [3, 1, 2]","[3, 1, 2] [3, 1, 2]","[1, 2, 3] [1, 2, 3]","[3, 1, 2] [1, 2, 3]"]}$c$::jsonb, $c$alias points to the same array; spread made a separate one.$c$, 1, 1, 'published', array[$c$reference$c$, $c$shared-mutation$c$]::text[]),
