('efde73b6-585c-5617-a03b-b6922a556c0d', $c$js-search-002$c$, $c$single_choice$c$, $c$What does this print?$c$, $c${"code":"const xs = [4, 8, 15];\nconsole.log(xs.find((n) => n > 5), xs.some((n) => n > 10), xs.every((n) => n > 3), [].every((n) => n > 3));","options":["8 true true true","[8, 15] true true false","8 true true false","8 false true true"]}$c$::jsonb, $c$find returns the first match; every is true for an empty array.$c$, 1, 1, 'published', array[$c$find$c$, $c$some$c$, $c$every$c$]::text[]),
('bdd9738a-f7ca-5d0b-8140-8afb9c549a29', $c$js-search-003$c$, $c$single_choice$c$, $c$After this code, which arrays are identical by reference?$c$, $c${"code":"const a = [2, 1];\nconst b = a.toSorted();\nconst c = a.sort();\nconst d = [...a];","options":["a and c","a and b","a and d","b and c"]}$c$::jsonb, $c$sort returns the same array it mutated; toSorted and spread create new ones.$c$, 2, 1, 'published', array[$c$immutability$c$, $c$toSorted$c$]::text[]),
