('58e290a5-dfe0-5373-9fd9-afbeae2baedf', $c$js-strings-003$c$, $c$single_choice$c$, $c$What does this print?$c$, $c${"code":"const t = 'a-b-c';\nconsole.log(t.replace('-', '+'), t.replaceAll('-', '+'), `${1 + 1} items`);","options":["'a+b-c' 'a+b+c' '2 items'","'a+b+c' 'a+b+c' '2 items'","'a+b-c' 'a+b+c' '1 + 1 items'","'a-b-c' 'a+b+c' '2 items'"]}$c$::jsonb, $c$replace changes the first match; replaceAll changes all; templates evaluate expressions.$c$, 1, 1, 'published', array[$c$replace$c$, $c$template-literals$c$]::text[]),
