('9ca9eda6-de6b-51b3-890d-3516a6bfd780', $c$js-json-001$c$, $c$single_choice$c$, $c$What does this print?$c$, $c${"code":"console.log(JSON.stringify({ a: undefined, b: () => 1, c: NaN, d: [undefined] }));","options":["'{\"c\":null,\"d\":[null]}'","'{\"a\":null,\"b\":null,\"c\":null,\"d\":[null]}'","'{\"c\":\"NaN\",\"d\":[]}'","It throws a TypeError"]}$c$::jsonb, $c$stringify omits undefined and functions in objects, uses null in arrays, and turns NaN into null.$c$, 1, 1, 'published', array[$c$JSON.stringify$c$]::text[]),
('b9c259cc-df0d-5db3-9f52-37b616c024c3', $c$js-json-002$c$, $c$single_choice$c$, $c$What does this print?$c$, $c${"code":"const saved = JSON.stringify({ when: new Date(0) });\nconst back = JSON.parse(saved);\nconsole.log(typeof back.when, back.when instanceof Date);","options":["'string' false","'object' true","'number' false","'object' false"]}$c$::jsonb, $c$Dates serialise to ISO strings and come back as strings.$c$, 1, 1, 'published', array[$c$JSON.parse$c$, $c$dates$c$]::text[]),
('226978ca-24dc-5cc7-993e-5b81858a4e1c', $c$js-json-003$c$, $c$single_choice$c$, $c$Which statement is correct?$c$, $c${"code":"const value = JSON.parse(localStorage.getItem('prefs'));","options":["If the key is missing, JSON.parse(null) returns null without throwing","If the key is missing, JSON.parse throws a SyntaxError","JSON.parse returns undefined for missing input","This line can never throw"]}$c$::jsonb, $c$getItem returns null for a missing key, and JSON.parse(null) parses the string 'null'.$c$, 1, 1, 'published', array[$c$JSON.parse$c$, $c$error-handling$c$]::text[]),
('95b7c263-c3ab-549b-99be-f9a313069b0f', $c$js-errors-001$c$, $c$single_choice$c$, $c$What does this print?$c$, $c${"code":"function test() {\n  try {\n    return 'try';\n  } finally {\n    console.log('cleanup');\n  }\n}\nconsole.log(test());","options":["cleanup then try","try then cleanup","try","cleanup"]}$c$::jsonb, $c$finally runs before the function actually returns.$c$, 2, 1, 'published', array[$c$finally$c$, $c$return$c$]::text[]),
('cf164272-cb5d-56d4-a7de-bb0aea124b12', $c$js-errors-002$c$, $c$single_choice$c$, $c$What happens?$c$, $c${"code":"try {\n  setTimeout(() => {\n    throw new Error('late');\n  }, 0);\n} catch (error) {\n  console.log('caught', error.message);\n}\nconsole.log('after');","options":["Prints 'after', then an uncaught error is reported","Prints 'caught late' then 'after'","Prints 'after' then 'caught late'","Nothing is printed"]}$c$::jsonb, $c$try/catch only covers code that runs synchronously inside the block.$c$, 2, 1, 'published', array[$c$try-catch$c$, $c$asynchronous$c$]::text[]),
