('65353b8c-5291-58ae-8620-366e884bcc45', $c$js-dom-003$c$, $c$single_choice$c$, $c$What does this print?$c$, $c${"code":"// <button id=\"b\" class=\"btn\" data-order-id=\"77\"></button>\nconst b = document.querySelector('#b');\nb.classList.toggle('active');\nb.classList.toggle('active');\nb.classList.add('btn');\nconsole.log(b.className, b.dataset.orderId);","options":["'btn' '77'","'btn active' '77'","'btn btn' '77'","'btn' 77"]}$c$::jsonb, $c$toggle twice returns to the start; add ignores duplicates; data-* values are strings.$c$, 1, 1, 'published', array[$c$classList$c$, $c$dataset$c$]::text[]),
('247c1512-4360-5037-92e5-04928b2fcf48', $c$js-nodes-001$c$, $c$single_choice$c$, $c$What does this print?$c$, $c${"code":"// <ul id=\"l\"><li>a</li><li>b</li></ul>\nconst l = document.querySelector('#l');\nconst first = l.firstElementChild;\nl.append(first);\nconsole.log(l.children.length, l.textContent);","options":["2 'ba'","3 'aba'","2 'ab'","3 'abb'"]}$c$::jsonb, $c$Appending an existing node moves it.$c$, 2, 1, 'published', array[$c$append$c$, $c$moving-nodes$c$]::text[]),
('b2562466-b0bf-50b7-99f9-5bcf25efb480', $c$js-nodes-002$c$, $c$single_choice$c$, $c$Why build list items inside a DocumentFragment before appending?$c$, $c${"code":"","options":["The fragment's children are inserted in one operation, avoiding repeated layout work","Elements cannot be appended to a list one at a time","Fragments automatically add event listeners","It is the only way to set textContent on new elements"]}$c$::jsonb, $c$A fragment is a lightweight container that empties into the DOM in one step.$c$, 1, 1, 'published', array[$c$createElement$c$, $c$DocumentFragment$c$]::text[]),
('86722b13-1184-5591-9320-009f846b8840', $c$js-nodes-003$c$, $c$single_choice$c$, $c$Which line removes every child of a container in one call?$c$, $c${"code":"","options":["container.replaceChildren()","container.remove()","container.innerHTML.clear()","container.children.forEach((c) => c.remove())"]}$c$::jsonb, $c$replaceChildren with no arguments empties the element.$c$, 1, 1, 'published', array[$c$remove$c$, $c$replaceChildren$c$]::text[]),
('b54e80d8-b469-591a-9da8-3d75325bde55', $c$js-events-001$c$, $c$single_choice$c$, $c$The user clicks the span. What does this print?$c$, $c${"code":"// <div id=\"box\"><span id=\"label\">Hi</span></div>\ndocument.querySelector('#box').addEventListener('click', (event) => {\n  console.log(event.target.id, event.currentTarget.id);\n});","options":["'label' 'box'","'box' 'box'","'label' 'label'","'box' 'label'"]}$c$::jsonb, $c$target is where the event started; currentTarget is where the listener is.$c$, 2, 1, 'published', array[$c$target$c$, $c$currentTarget$c$, $c$bubbling$c$]::text[]),
('74da49fe-f2b3-5a6c-9226-c199d23d20ab', $c$js-events-002$c$, $c$single_choice$c$, $c$Why does the listener keep firing after the second line?$c$, $c${"code":"button.addEventListener('click', () => console.log('hi'));\nbutton.removeEventListener('click', () => console.log('hi'));","options":["The two arrow functions are different objects, so nothing matches","removeEventListener needs a third argument","Click listeners cannot be removed","Arrow functions cannot be removed"]}$c$::jsonb, $c$Removal requires the same function reference.$c$, 2, 1, 'published', array[$c$removeEventListener$c$]::text[]),
('15837403-52f8-57bd-a0e6-fccc4ac35a13', $c$js-events-003$c$, $c$single_choice$c$, $c$What is the main benefit of this pattern?$c$, $c${"code":"list.addEventListener('click', (event) => {\n  const row = event.target.closest('li');\n  if (row) select(row.dataset.id);\n});","options":["One listener handles current and future rows via bubbling","It prevents the click from bubbling to document","It runs faster because closest is native","It avoids needing data attributes"]}$c$::jsonb, $c$Event delegation relies on bubbling.$c$, 2, 1, 'published', array[$c$delegation$c$, $c$closest$c$]::text[]),
