insert into public.practice_problems (id, slug, title, summary, prompt, topic, difficulty, estimated_minutes, starter_code, test_cases, hints, is_premium, position, status, technology, contract, constraints) values
('9a3abd6d-9f57-514e-a68f-641182e1c29c', $c$fizzbuzz-variant$c$, $c$FizzBuzz with custom rules$c$, $c$Order your conditions correctly to satisfy overlapping rules.$c$, $c$Write classify(n). Return 'FizzBuzz' when n is divisible by both 3 and 5, 'Fizz' when divisible by 3 only, 'Buzz' when divisible by 5 only, and the number itself (as a number) otherwise. Negative numbers and zero follow the same rules (0 is divisible by everything).$c$, $c$Control flow$c$, 1, 15, $c$function classify(n) {
  // Return 'Fizz', 'Buzz', 'FizzBuzz', or n.
}$c$, $c$[{"label":"multiple of 3","expression":"classify(9)","expected":"Fizz"},{"label":"multiple of 5","expression":"classify(10)","expected":"Buzz"},{"label":"multiple of both","expression":"classify(30)","expected":"FizzBuzz"},{"label":"neither","expression":"classify(7)","expected":7}]$c$::jsonb, $c$["Check the 'both' case before the single cases, or the single cases will win first.","n % 15 === 0 is the same as divisible by 3 and 5.","Return n unchanged (a number) in the final case."]$c$::jsonb, false, 7, 'published', 'javascript', $c${"signature":"classify(n: number): string | number","params":[{"name":"n","type":"integer"}],"returns":"'Fizz' | 'Buzz' | 'FizzBuzz' | number"}$c$::jsonb, $c$["n is an integer between -1000 and 1000","Return the number, not a string, when no rule applies"]$c$::jsonb),
('709abbd9-9122-5ab8-a8cc-bc9be312ff58', $c$sum-of-multiples$c$, $c$Sum of multiples below a limit$c$, $c$Loop with a stopping condition and avoid double counting.$c$, $c$Write sumMultiples(limit, factors). Return the sum of every positive integer below limit that is a multiple of at least one number in factors. Each qualifying integer is counted once even if it matches several factors. If factors is empty or limit is 1 or less, return 0.$c$, $c$Control flow$c$, 1, 15, $c$function sumMultiples(limit, factors) {
  // Sum integers below limit that are multiples of any factor.
}$c$, $c$[{"label":"classic 3 and 5 below 10","expression":"sumMultiples(10, [3, 5])","expected":23},{"label":"single factor","expression":"sumMultiples(20, [7])","expected":21},{"label":"no factors","expression":"sumMultiples(10, [])","expected":0}]$c$::jsonb, $c$["Loop n from 1 up to (but not including) limit.","some() answers 'is n divisible by any factor?' in one expression.","Adding n once per loop iteration avoids double counting automatically."]$c$::jsonb, false, 8, 'published', 'javascript', $c${"signature":"sumMultiples(limit: number, factors: number[]): number","params":[{"name":"limit","type":"integer"},{"name":"factors","type":"positive integer array"}],"returns":"number"}$c$::jsonb, $c$["1 <= limit <= 100000","factors contains positive integers"]$c$::jsonb),
('7b2f27f6-c9e4-56f2-9290-4767b07962b0', $c$validate-username$c$, $c$Validate a username$c$, $c$Apply several rules with guard clauses and return the first failure.$c$, $c$Write validateUsername(name). Return null when the username is valid, otherwise return the first failing rule's message, checked in this order: 'Required' when name is not a string or is empty after trimming; 'Too short' when fewer than 3 characters; 'Too long' when more than 16 characters; 'Invalid characters' when it contains anything other than letters, digits, or underscores; 'Must start with a letter' when the first character is not a letter. Do not trim the name before the length or character checks, only for the 'Required' check.$c$, $c$Control flow$c$, 1, 18, $c$function validateUsername(name) {
  // Return null when valid, otherwise the first failing message.
}$c$, $c$[{"label":"valid","expression":"validateUsername('ravi_07')","expected":null},{"label":"empty","expression":"validateUsername('   ')","expected":"Required"},{"label":"too short","expression":"validateUsername('ab')","expected":"Too short"},{"label":"bad characters","expression":"validateUsername('ravi-07')","expected":"Invalid characters"}]$c$::jsonb, $c$["typeof name !== 'string' handles non-strings before you call any string method.","A regular expression such as /^[A-Za-z0-9_]+$/ tests allowed characters.","Order matters: return as soon as a rule fails."]$c$::jsonb, false, 9, 'published', 'javascript', $c${"signature":"validateUsername(name: unknown): string | null","params":[{"name":"name","type":"any"}],"returns":"error message or null"}$c$::jsonb, $c$["Check rules in the exact order given","Letters are a–z and A–Z only"]$c$::jsonb),
('8a5fdb7c-4cab-50e1-aa19-8d6101ef8e56', $c$compose-greeting$c$, $c$Compose a greeting$c$, $c$Build small functions and combine them.$c$, $c$Write three functions. capitalize(word) returns the word with its first character upper-cased and the rest unchanged (empty string stays empty). exclaim(text) appends '!'. greet(name) returns 'Hello, ' followed by capitalize(name) followed by '!' by using the other two functions. Then write compose(f, g) that returns a new function h where h(x) equals f(g(x)).$c$, $c$Functions$c$, 1, 15, $c$function capitalize(word) {}

function exclaim(text) {}

function greet(name) {}

function compose(f, g) {}$c$, $c$[{"label":"capitalize","expression":"capitalize('asha')","expected":"Asha"},{"label":"greet","expression":"greet('asha')","expected":"Hello, Asha!"},{"label":"compose order","expression":"compose(exclaim, capitalize)('go')","expected":"Go!"}]$c$::jsonb, $c$["word[0] is undefined for an empty string; guard for that.","greet can be written as exclaim('Hello, ' + capitalize(name)).","compose returns (x) => f(g(x)); g runs first."]$c$::jsonb, false, 10, 'published', 'javascript', $c${"signature":"capitalize(word: string): string; exclaim(text: string): string; greet(name: string): string; compose(f, g): (x) => any","params":[],"returns":"see each function"}$c$::jsonb, $c$["greet must call capitalize and exclaim rather than building the string from scratch","compose returns a function"]$c$::jsonb),
('070358df-ac64-55f5-8b26-a5d655dfeaf6', $c$average-of-arguments$c$, $c$Average of any number of arguments$c$, $c$Use a rest parameter and a default value.$c$, $c$Write average(precision = 2, ...values). Return the arithmetic mean of values rounded to precision decimal places, as a number. If no values are given, return 0. Passing undefined as the first argument must use the default precision of 2.$c$, $c$Functions$c$, 1, 12, $c$function average(precision = 2, ...values) {
  // Return the mean rounded to precision decimals.
}$c$, $c$[{"label":"basic","expression":"average(2, 1, 2, 4)","expected":2.33},{"label":"default precision","expression":"average(undefined, 1, 2)","expected":1.5},{"label":"no values","expression":"average(2)","expected":0}]$c$::jsonb, $c$["values is a real array, so reduce works.","Number(x.toFixed(p)) converts the rounded string back to a number.","Guard for values.length === 0 before dividing."]$c$::jsonb, false, 11, 'published', 'javascript', $c${"signature":"average(precision?: number, ...values: number[]): number","params":[{"name":"precision","type":"integer, default 2"},{"name":"values","type":"numbers"}],"returns":"number"}$c$::jsonb, $c$["Return a number, not a string","0 <= precision <= 6"]$c$::jsonb),
('31a1fb15-cc09-5fa3-a968-bccd67906d19', $c$make-multiplier$c$, $c$Make a multiplier (and a counter)$c$, $c$Return configured functions that remember their settings.$c$, $c$Write makeMultiplier(factor) that returns a function multiplying its argument by factor. Then write makeCounter(start = 0) that returns an object with two methods: next() returns the current value and then increases it by 1, and reset() sets the value back to start. Counters created separately must not share state.$c$, $c$Functions$c$, 2, 18, $c$function makeMultiplier(factor) {}

function makeCounter(start = 0) {}$c$, $c$[{"label":"multiplier","expression":"makeMultiplier(3)(4)","expected":12},{"label":"counter sequence","expression":"(() => { const c = makeCounter(); return [c.next(), c.next(), c.next()]; })()","expected":[0,1,2]},{"label":"counter reset","expression":"(() => { const c = makeCounter(5); c.next(); c.reset(); return c.next(); })()","expected":5}]$c$::jsonb, $c$["The returned function closes over factor.","Keep the counter's current value in a let inside makeCounter, not on the returned object, so it is private.","reset must restore the original start, so keep start unchanged."]$c$::jsonb, false, 12, 'published', 'javascript', $c${"signature":"makeMultiplier(factor: number): (n: number) => number; makeCounter(start?: number): { next(): number; reset(): void }","params":[],"returns":"see each function"}$c$::jsonb, $c$["Do not use global variables for the counter state"]$c$::jsonb),
('f714c52c-d464-54e9-8eca-61f1e5cce0d8', $c$count-words$c$, $c$Count words with an object$c$, $c$Use an object as a tally with bracket notation.$c$, $c$Write countWords(text). Split the text on any whitespace, ignore empty pieces, lower-case each word, strip leading and trailing punctuation from the set . , ! ? ; : and return a plain object mapping each word to how many times it appears. Return an empty object for empty or whitespace-only input.$c$, $c$Objects$c$, 1, 15, $c$function countWords(text) {
  // Return { word: count, ... }.
}$c$, $c$[{"label":"simple","expression":"countWords('tea tea cake')","expected":{"tea":2,"cake":1}},{"label":"case and punctuation","expression":"countWords('Go, go, GO!')","expected":{"go":3}},{"label":"empty","expression":"countWords('   ')","expected":{}}]$c$::jsonb, $c$["text.trim().split(/\\s+/) splits on runs of whitespace.","A regex like /^[.,!?;:]+|[.,!?;:]+$/g removes punctuation at the ends only.","Use (counts[word] ?? 0) + 1 — but beware inherited keys like 'constructor'; Object.hasOwn or a null-prototype object avoids surprises."]$c$::jsonb, false, 13, 'published', 'javascript', $c${"signature":"countWords(text: string): Record<string, number>","params":[{"name":"text","type":"string"}],"returns":"object of word counts"}$c$::jsonb, $c$["Keys are lower-case words with surrounding punctuation removed","Use a plain object, not a Map"]$c$::jsonb),
('5af132ef-2acb-5e30-9c50-99383b95804b', $c$bank-account-object$c$, $c$Bank account object$c$, $c$Methods that share state through this and survive being detached.$c$, $c$Write createAccount(owner, opening = 0) returning an object with: balance (a number), deposit(amount) which adds a positive amount and returns the new balance, withdraw(amount) which subtracts a positive amount that does not exceed the balance and returns the new balance, and statement() returning `${owner}: ${balance}`. deposit and withdraw must throw a RangeError for non-positive amounts and withdraw must throw a RangeError for insufficient funds. The methods must keep working when extracted from the object, for example const w = account.withdraw; w(10).$c$, $c$Objects$c$, 2, 20, $c$function createAccount(owner, opening = 0) {
  // Return an account object.
}$c$, $c$[{"label":"deposit","expression":"createAccount('Ann', 100).deposit(50)","expected":150},{"label":"withdraw","expression":"createAccount('Ann', 100).withdraw(30)","expected":70},{"label":"statement","expression":"(() => { const a = createAccount('Ann', 10); a.deposit(5); return a.statement(); })()","expected":"Ann: 15"}]$c$::jsonb, $c$["A detached call has no this, so either use arrow functions that close over a local variable, or bind each method.","Keep the balance in a closure variable and expose it through a getter, or update both.","Validate the amount before changing anything."]$c$::jsonb, false, 14, 'published', 'javascript', $c${"signature":"createAccount(owner: string, opening?: number): { balance: number; deposit(n): number; withdraw(n): number; statement(): string }","params":[],"returns":"account object"}$c$::jsonb, $c$["Throw RangeError for invalid amounts","Detached methods must still operate on the same account"]$c$::jsonb),
('224dc98b-40ee-528e-9e78-bc23d5fc6613', $c$extract-address$c$, $c$Extract an address safely$c$, $c$Nested destructuring with defaults and optional chaining on incomplete records.$c$, $c$Write formatAddress(user). user may be missing entirely or missing any nested part. Read user.profile.address.{line1, city, postcode, country}. Return a single string joining the non-empty parts of line1, city, postcode with ', ' followed by ' (' + country + ')' where country defaults to 'IN'. If no address parts are available at all, return 'No address'.$c$, $c$Objects$c$, 2, 15, $c$function formatAddress(user) {
  // Return the formatted address or 'No address'.
}$c$, $c$[{"label":"full address","expression":"formatAddress({ profile: { address: { line1: '12 MG Road', city: 'Pune', postcode: '411001', country: 'IN' } } })","expected":"12 MG Road, Pune, 411001 (IN)"},{"label":"default country","expression":"formatAddress({ profile: { address: { city: 'Pune' } } })","expected":"Pune (IN)"},{"label":"no user","expression":"formatAddress()","expected":"No address"}]$c$::jsonb, $c$["const { line1 = '', city = '', postcode = '', country = 'IN' } = user?.profile?.address ?? {};","Collect the parts in an array and filter(Boolean) before joining.","Decide on 'No address' by checking whether the filtered parts array is empty."]$c$::jsonb, true, 15, 'published', 'javascript', $c${"signature":"formatAddress(user?: object): string","params":[{"name":"user","type":"object or undefined"}],"returns":"string"}$c$::jsonb, $c$["Must not throw for undefined input or missing nested objects","Empty strings count as missing"]$c$::jsonb),
('25d9bf3b-18ef-5bb5-85b2-5f6d35424f17', $c$queue-simulation$c$, $c$Queue simulation$c$, $c$Apply push, shift, and splice and report what was removed.$c$, $c$Write processQueue(initial, operations). Start with a copy of initial (do not mutate it). Each operation is an array: ['enqueue', item] adds to the end; ['dequeue'] removes from the front; ['remove', item] removes the first occurrence of item if present. Return an object { queue, removed } where queue is the final array and removed lists every item that was removed by dequeue or remove, in order.$c$, $c$Arrays$c$, 1, 15, $c$function processQueue(initial, operations) {
  // Return { queue, removed }.
}$c$, $c$[{"label":"enqueue and dequeue","expression":"processQueue(['a'], [['enqueue', 'b'], ['dequeue']])","expected":{"queue":["b"],"removed":["a"]}},{"label":"remove middle","expression":"processQueue(['a', 'b', 'c'], [['remove', 'b']])","expected":{"queue":["a","c"],"removed":["b"]}},{"label":"dequeue empty","expression":"processQueue([], [['dequeue']])","expected":{"queue":[],"removed":[]}}]$c$::jsonb, $c$["Start with const queue = [...initial].","shift() returns undefined on an empty array; only record it when the queue had items.","indexOf then splice(index, 1) removes one occurrence; splice returns the removed items."]$c$::jsonb, false, 16, 'published', 'javascript', $c${"signature":"processQueue(initial: any[], operations: any[][]): { queue: any[]; removed: any[] }","params":[],"returns":"{ queue, removed }"}$c$::jsonb, $c$["initial must not be mutated","dequeue on an empty queue does nothing"]$c$::jsonb),
('5e476fac-5a45-5b07-90c7-10909c57b19e', $c$cart-summary$c$, $c$Cart summary$c$, $c$Chain filter, map, and reduce on an order list.$c$, $c$Write summarize(items). Each item is { name, price, qty, taxable }. Ignore items with qty of 0 or less. Return { count, subtotal, tax, total, names } where count is the number of items kept, subtotal is the sum of price × qty, tax is 18% of the subtotal of taxable items only, total is subtotal + tax, and names is an array of the kept item names in original order. Round subtotal, tax, and total to 2 decimals as numbers.$c$, $c$Arrays$c$, 2, 20, $c$function summarize(items) {
  // Return { count, subtotal, tax, total, names }.
}$c$, $c$[{"label":"mixed cart","expression":"summarize([{ name: 'Tea', price: 40, qty: 2, taxable: true }, { name: 'Cake', price: 120, qty: 1, taxable: false }, { name: 'Water', price: 20, qty: 0, taxable: true }])","expected":{"count":2,"subtotal":200,"tax":14.4,"total":214.4,"names":["Tea","Cake"]}},{"label":"empty cart","expression":"summarize([])","expected":{"count":0,"subtotal":0,"tax":0,"total":0,"names":[]}},{"label":"single taxable item","expression":"summarize([{ name: 'Tea', price: 100, qty: 1, taxable: true }])","expected":{"count":1,"subtotal":100,"tax":18,"total":118,"names":["Tea"]}}]$c$::jsonb, $c$["Filter once into a kept array and reuse it for count, names, and totals.","Compute the taxable subtotal separately with another filter/reduce.","A helper round2 = (n) => Math.round(n * 100) / 100 keeps results numeric."]$c$::jsonb, false, 17, 'published', 'javascript', $c${"signature":"summarize(items: Array<{ name: string; price: number; qty: number; taxable: boolean }>): { count: number; subtotal: number; tax: number; total: number; names: string[] }","params":[],"returns":"summary object"}$c$::jsonb, $c$["Do not mutate items","Round with 2 decimals; return numbers"]$c$::jsonb),
('ebf2acd1-6233-5cc4-a1f2-b7ca891c9ae6', $c$top-scores$c$, $c$Top scores with tie-breaks$c$, $c$A multi-key comparator that must not mutate the input.$c$, $c$Write topScores(players, n). players is an array of { name, score }. Return a new array of the top n players sorted by score descending, then by name ascending (case-insensitive) for equal scores. If n is larger than the number of players, return all of them. The input array must not be reordered.$c$, $c$Arrays$c$, 2, 18, $c$function topScores(players, n) {
  // Return the top n players.
}$c$, $c$[{"label":"top two","expression":"topScores([{ name: 'Bo', score: 80 }, { name: 'Al', score: 95 }, { name: 'Cy', score: 80 }], 2)","expected":[{"name":"Al","score":95},{"name":"Bo","score":80}]},{"label":"n larger than list","expression":"topScores([{ name: 'Zed', score: 1 }], 5)","expected":[{"name":"Zed","score":1}]},{"label":"tie broken by name","expression":"topScores([{ name: 'Zed', score: 50 }, { name: 'Amy', score: 50 }], 1)","expected":[{"name":"Amy","score":50}]}]$c$::jsonb, $c$["toSorted (or [...players].sort) keeps the original untouched.","b.score - a.score sorts descending; use || to fall through to the name comparison when it is 0.","a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }) compares case-insensitively; slice(0, n) takes the top n."]$c$::jsonb, true, 18, 'published', 'javascript', $c${"signature":"topScores(players: Array<{ name: string; score: number }>, n: number): Array<{ name: string; score: number }>","params":[],"returns":"new sorted array of length min(n, players.length)"}$c$::jsonb, $c$["Do not mutate players","Names compare case-insensitively"]$c$::jsonb),
('1c106747-112c-513e-b8e4-57b8f97b77a4', $c$title-case$c$, $c$Title case a sentence$c$, $c$split, map, slice, and join working together.$c$, $c$Write titleCase(text). Return the text with the first letter of every word upper-cased and the remaining letters lower-cased. Words are separated by single spaces in the output regardless of how many spaces separated them in the input. Leading and trailing whitespace is removed. Empty input returns an empty string.$c$, $c$Strings$c$, 1, 12, $c$function titleCase(text) {
