('7b2f27f6-c9e4-56f2-9290-4767b07962b0', $c$[{"label":"not a string","expression":"validateUsername(42)","expected":"Required"},{"label":"too long","expression":"validateUsername('abcdefghijklmnopq')","expected":"Too long"},{"label":"starts with digit","expression":"validateUsername('7ravi')","expected":"Must start with a letter"},{"label":"starts with underscore","expression":"validateUsername('_ravi')","expected":"Must start with a letter"},{"label":"exactly 16 chars","expression":"validateUsername('abcdefghijklmnop')","expected":null}]$c$::jsonb, 1),
