('31a1fb15-cc09-5fa3-a968-bccd67906d19', $c$[{"label":"independent counters","expression":"(() => { const a = makeCounter(); const b = makeCounter(10); a.next(); a.next(); return [a.next(), b.next()]; })()","expected":[2,10]},{"label":"independent multipliers","expression":"(() => { const d = makeMultiplier(2); const t = makeMultiplier(3); return [d(5), t(5)]; })()","expected":[10,15]},{"label":"multiplier with zero","expression":"makeMultiplier(0)(99)","expected":0}]$c$::jsonb, 1),
