('a562ff46-8339-5e3d-8dfe-cc7158fd1a40', $c$[{"label":"lazy evaluation","expression":"(() => { const r = createRegistry(); let runs = 0; r.define('lazy', () => { runs++; return {}; }); return runs; })()","expected":0},{"label":"dependencies via require","expression":"(() => { const r = createRegistry(); r.define('math', () => ({ double: (n) => n * 2 })); r.define('app', (req) => ({ result: req('math').double(21) })); return r.require('app').result; })()","expected":42},{"label":"redefine after require ignored","expression":"(() => { const r = createRegistry(); r.define('x', () => ({ v: 1 })); r.require('x'); r.define('x', () => ({ v: 2 })); return r.require('x').v; })()","expected":1}]$c$::jsonb, 1),
